using SprintPilot.Application;
using SprintPilot.Domain;
namespace SprintPilot.Infrastructure;
public sealed class DemoTracker:IWorkTracker {
 readonly Dictionary<int,WorkItem> items=new();readonly Dictionary<int,List<WorkItemComment>> comments=new();readonly Metadata metadata;readonly object sync=new();readonly List<GitBranch> demoBranches=[];readonly List<GitPullRequest> demoPullRequests=[];
 public DemoTracker(){var today=DateTimeOffset.UtcNow.Date;var monday=today.AddDays(-((int)today.DayOfWeek+6)%7);var iterations=Enumerable.Range(-1,3).Select(i=>new Iteration((i+2).ToString(),$"Sprint {18+i}",$"SprintPilot\\Sprint {18+i}",monday.AddDays(i*14),monday.AddDays(i*14+13))).ToArray();
  Person[] people=[new("kevin","Kevin","kevin@example.test"),new("johan","Johan","johan@example.test"),new("piotr","Piotr","piotr@example.test"),new("bea","Bea","bea@example.test")];
  string[] fields=["System.Title","System.AssignedTo","System.State","System.IterationPath","System.AreaPath","Microsoft.VSTS.Scheduling.StoryPoints","Microsoft.VSTS.Common.Priority","System.Tags","System.Description","Microsoft.VSTS.Common.AcceptanceCriteria"];
  metadata=new([new("demo","Platform team")],people,iterations,["SprintPilot\\Platform","SprintPilot\\Experience"],[..new[]{"Product Backlog Item","Bug","Task"}.Select(n=>new TypeDefinition(n,[new("New","Proposed"),new("Active","InProgress"),new("Resolved","Resolved"),new("Closed","Completed")],fields,"Microsoft.VSTS.Scheduling.StoryPoints"))],[new("SprintPilot",true)],people[0]);
  string[] titles=["Pablo API timeout handling","CNX migration validation","Automate DR deployment pipeline","FrontCare account recovery","Review database failover alerts","Improve claim search latency","Document rollback procedure","Add migration failure notification","Handle duplicate queue messages","Review API contract changes","Verify session expiry behavior","Clean up obsolete feature flags"];
  for(int i=0;i<titles.Length;i++){var owner=people[i%4];items[5210+i]=new(){Id=5210+i,Revision=1,Title=titles[i],Type=i%4==0?"Bug":"Product Backlog Item",Owner=i%5==0?"":owner.Name,OwnerId=i%5==0?"":owner.Id,State=i%4==0?"New":i%4==3?"Closed":"Active",Iteration=iterations[i<9?1:0].Path,Area=metadata.Areas[i%2],Estimate=i%3==0?null:i%5+1,Priority=i%3+1,Parent=i%4==0?null:5000,Tags=i%3==0?[]:[i%2==0?"API":"DR","Platform"],Changed=DateTimeOffset.UtcNow.AddDays(-i*2),Description="<p>Improve the reliability of this workflow. Preserve existing behavior and document the operational impact.</p>",Acceptance="<p>Given a valid request, when the workflow completes, then the expected result is available.</p><p>Testing: cover success and failure paths.</p>"};}
  foreach(var item in PlanningExample.Create(DateOnly.FromDateTime(DateTime.Now)).Items)items[item.Id]=item;
  demoBranches.AddRange([
   new("main","1111111111111111111111111111111111111111","Kevin","Kevin",DateTimeOffset.UtcNow.AddDays(-1),"Merge current sprint changes",true,true,false,true),
   new("feature/frontcare-recovery","2222222222222222222222222222222222222222","Bea","Bea",DateTimeOffset.UtcNow.AddDays(-12),"Add recovery validation",false,false,true,false),
   new("feature/old-claim-search","3333333333333333333333333333333333333333","Johan","Johan",DateTimeOffset.UtcNow.AddDays(-126),"Finish claim search optimization",false,false,false,true),
   new("bugfix/legacy-timeout","4444444444444444444444444444444444444444","Piotr","Piotr",DateTimeOffset.UtcNow.AddDays(-224),"Handle legacy timeout response",false,false,false,false),
   new("release/2025-q4","5555555555555555555555555555555555555555","Kevin","Kevin",DateTimeOffset.UtcNow.AddDays(-270),"Prepare Q4 release",false,false,false,true),
   new("experiment/queue-prototype","6666666666666666666666666666666666666666","Johan","Johan",DateTimeOffset.UtcNow.AddDays(-38),"Prototype queue routing",false,false,false,false)
  ]);
  demoPullRequests.AddRange([
   new(41,"FrontCare recovery validation","feature/frontcare-recovery","main","Bea",DateTimeOffset.UtcNow.AddDays(-10),false,"2222222222222222222222222222222222222222","Bea",DateTimeOffset.UtcNow.AddDays(-2),"Address review feedback",2,1,0,"succeeded","https://dev.azure.com/demo/SprintPilot/_git/SprintPilot/pullrequest/41"),
   new(42,"Old claim search experiment","feature/old-claim-search","main","Johan",DateTimeOffset.UtcNow.AddDays(-145),true,"3333333333333333333333333333333333333333","Johan",DateTimeOffset.UtcNow.AddDays(-126),"Finish claim search optimization",1,0,0,"notSet","https://dev.azure.com/demo/SprintPilot/_git/SprintPilot/pullrequest/42"),
   new(43,"Legacy timeout cleanup","bugfix/legacy-timeout","main","Piotr",DateTimeOffset.UtcNow.AddDays(-260),false,"4444444444444444444444444444444444444444","Piotr",DateTimeOffset.UtcNow.AddDays(-224),"Handle legacy timeout response",2,0,0,"conflicts","https://dev.azure.com/demo/SprintPilot/_git/SprintPilot/pullrequest/43"),
   new(44,"Release 2025 Q4","release/2025-q4","main","Kevin",DateTimeOffset.UtcNow.AddDays(-280),false,"5555555555555555555555555555555555555555","Kevin",DateTimeOffset.UtcNow.AddDays(-270),"Prepare Q4 release",3,0,0,"notSet","https://dev.azure.com/demo/SprintPilot/_git/SprintPilot/pullrequest/44"),
   new(45,"Queue routing prototype","experiment/queue-prototype","main","Johan",DateTimeOffset.UtcNow.AddDays(-40),true,"6666666666666666666666666666666666666666","Johan",DateTimeOffset.UtcNow.AddDays(-38),"Prototype queue routing",0,0,0,"notSet","https://dev.azure.com/demo/SprintPilot/_git/SprintPilot/pullrequest/45"),
   new(46,"Waiting on architecture decision","feature/architecture-decision","main","Kevin",DateTimeOffset.UtcNow.AddDays(-190),false,"8888888888888888888888888888888888888888","Kevin",DateTimeOffset.UtcNow.AddDays(-181),"Update architecture options",2,0,1,"notSet","https://dev.azure.com/demo/SprintPilot/_git/SprintPilot/pullrequest/46")
