 }
 public Task<Person> TestAsync(Credentials c,CancellationToken ct=default)=>Task.FromResult(metadata.Me);
 public Task<Metadata> MetadataAsync(bool refresh=false,CancellationToken ct=default)=>Task.FromResult(metadata);
 public Task<IReadOnlyList<WorkItem>> SprintAsync(string iteration,CancellationToken ct=default){lock(sync){var rows=items.Values.Where(i=>i.Iteration==iteration).OrderBy(i=>i.Order??double.MaxValue).ThenBy(i=>i.Id).Select((w,i)=>w with{Order=i+1}).ToArray();return Task.FromResult<IReadOnlyList<WorkItem>>(rows);}}
 public Task ReorderSprintAsync(string iterationId,string iterationPath,int id,int previousId,int nextId,CancellationToken ct=default){lock(sync){var rows=items.Values.Where(i=>i.Iteration==iterationPath).OrderBy(i=>i.Order??double.MaxValue).ThenBy(i=>i.Id).ToList();var item=rows.FirstOrDefault(i=>i.Id==id)??throw new TrackerException("Demo sprint item not found.");rows.Remove(item);var index=previousId==0?0:rows.FindIndex(i=>i.Id==previousId)+1;if(nextId!=0){var next=rows.FindIndex(i=>i.Id==nextId);if(next>=0)index=next;}index=Math.Clamp(index,0,rows.Count);rows.Insert(index,item);for(var i=0;i<rows.Count;i++)items[rows[i].Id]=rows[i] with{Order=i+1};return Task.CompletedTask;}}
 public Task<SprintCapacity> CapacityAsync(string iterationId,CancellationToken ct=default){var sprint=metadata.Iterations.FirstOrDefault(i=>i.Id==iterationId);if(sprint?.Start is not {} start)return Task.FromResult(new SprintCapacity([],[]));var members=metadata.People.Select((p,i)=>new MemberCapacity(p.Id,p.Name,i==1?[new DateRange(start.AddDays(3),start.AddDays(3))]:[],6)).ToArray();return Task.FromResult(new SprintCapacity(members,[]));}
 public Task<IReadOnlyList<AzureProject>> ProjectsAsync(CancellationToken ct=default)=>Task.FromResult<IReadOnlyList<AzureProject>>([new("demo","SprintPilot"),new("archive","Archive tools")]);
 public Task<IReadOnlyList<GitRepository>> RepositoriesAsync(string project,CancellationToken ct=default)=>Task.FromResult<IReadOnlyList<GitRepository>>(project=="Archive tools"?[new("archive-repo","Migration archive","main")]:[new("demo-repo","SprintPilot","main"),new("demo-api","Pablo API","main")]);
 public Task<IReadOnlyList<GitBranch>> BranchesAsync(string project,string repositoryId,CancellationToken ct=default){lock(sync)return Task.FromResult<IReadOnlyList<GitBranch>>(repositoryId=="demo-repo"?demoBranches.ToArray():[new("main","7777777777777777777777777777777777777777","Kevin","Kevin",DateTimeOffset.UtcNow.AddDays(-3),"Repository baseline",true,true,false,true)]);}
 public Task<IReadOnlyList<BranchDeleteResult>> DeleteBranchesAsync(string project,string repositoryId,IReadOnlyList<BranchDeleteRequest> branches,CancellationToken ct=default){lock(sync){var result=new List<BranchDeleteResult>();foreach(var request in branches){var found=demoBranches.FirstOrDefault(b=>b.Name.Equals(request.Name,StringComparison.OrdinalIgnoreCase)&&b.ObjectId.Equals(request.ObjectId,StringComparison.OrdinalIgnoreCase));if(found is null){result.Add(new(request.Name,false,"Branch changed or no longer exists. Refresh and review it again."));continue;}if(found.IsDefault||found.IsLocked){result.Add(new(request.Name,false,"Default or locked branches cannot be deleted."));continue;}demoBranches.Remove(found);result.Add(new(request.Name,true,null));}return Task.FromResult<IReadOnlyList<BranchDeleteResult>>(result);}}
 public Task<IReadOnlyList<GitPullRequest>> PullRequestsAsync(string project,string repositoryId,CancellationToken ct=default){lock(sync)return Task.FromResult<IReadOnlyList<GitPullRequest>>(repositoryId=="demo-repo"?demoPullRequests.ToArray():[]);}
 public Task<IReadOnlyList<GitPullRequestSignal>> PullRequestSignalsAsync(string project,string repositoryId,CancellationToken ct=default){lock(sync)return Task.FromResult<IReadOnlyList<GitPullRequestSignal>>(repositoryId=="demo-repo"?demoPullRequests.Select(p=>new GitPullRequestSignal(p.Id,p.Title,p.SourceBranch,"active",p.CreatedDate)).ToArray():[]);}
 public Task<IReadOnlyList<PullRequestAbandonResult>> AbandonPullRequestsAsync(string project,string repositoryId,IReadOnlyList<PullRequestAbandonRequest> pullRequests,CancellationToken ct=default){lock(sync){var result=new List<PullRequestAbandonResult>();foreach(var request in pullRequests){var found=demoPullRequests.FirstOrDefault(p=>p.Id==request.Id);if(found is null){result.Add(new(request.Id,false,"Pull request is no longer active. Refresh before retrying."));continue;}if(!found.SourceCommitId.Equals(request.SourceCommitId,StringComparison.OrdinalIgnoreCase)){result.Add(new(request.Id,false,"The source branch changed after review. Refresh and review the pull request again."));continue;}demoPullRequests.Remove(found);result.Add(new(request.Id,true,null));}return Task.FromResult<IReadOnlyList<PullRequestAbandonResult>>(result);}}
 public Task<IReadOnlyList<WorkItem>> PlanningAsync(string[] types,CancellationToken ct=default){lock(sync)return Task.FromResult<IReadOnlyList<WorkItem>>(items.Values.Where(w=>types.Contains(w.Type)).ToArray());}
 public Task<WorkItem> GetAsync(int id,CancellationToken ct=default){lock(sync)return Task.FromResult(items.GetValueOrDefault(id)??throw new TrackerException("Demo item not found."));}
 public Task<IReadOnlyList<WorkItemComment>> CommentsAsync(int id,CancellationToken ct=default){lock(sync)return Task.FromResult<IReadOnlyList<WorkItemComment>>(comments.GetValueOrDefault(id)??[]);}
 public Task<WorkItemComment> AddCommentAsync(int id,string text,CancellationToken ct=default){lock(sync){if(!items.ContainsKey(id))throw new TrackerException("Demo item not found.");if(string.IsNullOrWhiteSpace(text))throw new TrackerException("Enter a comment first.");var list=comments.GetValueOrDefault(id);if(list is null){list=[];comments[id]=list;}var comment=new WorkItemComment(list.Count+1,text.Trim(),metadata.Me.Name,DateTimeOffset.UtcNow);list.Add(comment);items[id]=items[id] with{CommentCount=list.Count,Changed=DateTimeOffset.UtcNow};return Task.FromResult(comment);}}
 public Task<WorkItem> UpdateAsync(ItemUpdate u,CancellationToken ct=default){lock(sync){if(items[u.Original.Id].Revision!=u.Original.Revision)throw new TrackerException("Revision conflict. Refresh before retrying.");var item=ItemChanges.Apply(u.Original,u.Changes,metadata) with{Revision=u.Original.Revision+1,Changed=DateTimeOffset.UtcNow};items[item.Id]=item;return Task.FromResult(item);}}
 public Task<WorkItem> CreateAsync(string type,IReadOnlyList<Change> changes,int? parent,CancellationToken ct=default){lock(sync){var item=ItemChanges.Apply(new(){Id=items.Keys.Max()+1,Revision=1,Type=type,State="New",Parent=parent,Changed=DateTimeOffset.UtcNow},changes,metadata);items[item.Id]=item;return Task.FromResult(item);}}

 public Task<IReadOnlyList<string>> PipelineYamlFilesAsync(string project,string repositoryId,string branch,CancellationToken ct=default)=>Task.FromResult<IReadOnlyList<string>>(new[]{"/azure-pipelines.yml","/pipelines/deploy.yml","/pipelines/infrastructure.yml"});
 public Task<IReadOnlyList<PipelineDefinition>> PipelinesAsync(string project,CancellationToken ct=default)=>Task.FromResult<IReadOnlyList<PipelineDefinition>>(Array.Empty<PipelineDefinition>());
 public Task<IReadOnlyList<PipelineCreateResult>> CreatePipelinesAsync(string project,string repositoryId,string branch,IReadOnlyList<PipelineCreateRequest> pipelines,CancellationToken ct=default)=>Task.FromResult<IReadOnlyList<PipelineCreateResult>>(pipelines.Select((p,i)=>new PipelineCreateResult(p.Name,true,1000+i,null)).ToArray());
}
